function UIMazeDialog:OnOpenViewMiniMap()
    KTool.SetActive(self.bigMap.gameObject, true)
    KTool.SetActive(self.smallMap.gameObject, false)

    --第一次的时候会初始化一次大地图，之后和小地图一起更新
    if not self.isFillViewMap then
        self:FillViewMap(MazeMapMgr:GetInstance():GetPointByType(Constants.MazePointType.StartPoint))
        self.isFillViewMap = true
    end

    self:SetUIActive(false)
    self:RefeshBackWithBigMap()

    self:RefeshViewMapPos()
    self.isShowBigMap = true
end

--刷新大地图位置， 移动到当前点的坐标
function UIMazeDialog:RefeshViewMapPos()
    local curPoint = MazeMapMgr:GetInstance().curPoint
    --大地图动画移动
    local curPointGo = self.viewMmap.transform:Find("point"..curPoint.line..curPoint.row)
    if curPointGo then
        local viewY = self.viewMmap.transform.parent.parent:GetComponent(typeof(RectTransform)).rect.height * 0.5
        local tarY = viewY - curPointGo.localPosition.y

        local viewMapRc = self.viewMmap.transform:GetComponent(typeof(RectTransform)).rect.height
        --如果该点的y值小于视图的一半或者大于content - 视图/2 
        if math.abs(curPointGo.localPosition.y) <= viewY then
            tarY = 0
        elseif math.abs(curPointGo.localPosition.y) >= (math.abs(viewMapRc) - viewY * 2) then
            --坐标是要负的
            tarY = viewY * 2 - math.abs(viewMapRc)
        end

        local viewPos = self.viewMmap.transform.localPosition
        --点坐标大于rect的一半 且 差距大于10才做移动  view 滑动可能出现坐标不准
        if math.abs(math.abs(viewPos.y) - math.abs(tarY)) >= 10 then 
            CfUtils.DoTween(0.5, function(updateView)
                self.viewMmap.transform.localPosition = Vector3(viewPos.x, viewPos.y + (tarY - viewPos.y) * updateView, viewPos.x)
            end)
        end
    end
end

--关闭大地图
