--刷新可到达搜查点信息   
function UIMazeDialog:RefeshPointMessage(isUpdateViewGoPos)
    --如果不是只更新位置，清空一下上个视图点
    if not isUpdateViewGoPos then
        --先回收上个关卡所有的视图点
        self:ClearPointMessageAll()
    end

    local preViews = MazeMgr:GetInstance():GetCurPreViewData()
    if not preViews then return end

    for k, v in pairs(preViews) do
        if isUpdateViewGoPos then
            self:UpdatePointViewGoPos(v)
        else
            self:FillPoint(v)
        end
    end
end 

--绘制可到达搜查点点信息 
function UIMazeDialog:FillPoint(point)
    if not point then return end
    table.insert(self.lastPreviewPoint, point)

    local go = point.viewGo
    if not go then
        go = self:GetPointGo()
        go.name = "pointPreView"
        go.transform.localScale = Vector3(1,1,1)
        MazeMapMgr:GetInstance():SetPointViewGo(point, go)
    end
    self:UpdatePointViewGoPos(point)

    CfUtils.FillImage(go, CfUtils.GetMazePreviewPath(point), true)
    local btn = go.transform:Find("btn"):GetComponent(typeof(Button))
    btn.onClick:RemoveAllListeners()
    btn.onClick:AddListener(function()
        --self:SetUIActive(false)
        if MazeMapMgr:GetInstance():IsCurPoint(point) then
            MazeMgr:GetInstance():ActiveEvent()
        else
            if not MazeMapMgr:GetInstance():IsSamePoint(MazeMapMgr:GetInstance().viewPoint, point) then
                --CfUtils.CloseUIDialog(Constants.UITypeIds.UIViewPointEventDialog, "UIViewPointEventDialog")
                --MazePlayerMgr:GetInstance():PlayerLookPoint(point, function()
                    MazeMapMgr:GetInstance().viewPoint = point
                    UIModule.OpenDialog({id = Constants.UITypeIds.UIViewPointEventDialog, parameters = {point = point}})
                --end)
            end
        end
    end)

    --特效部分
    local effectGo = point.effectGo
    if not effectGo then
        effectGo = self:GetPointEffectGo(point.type)
        effectGo.transform.position = MazeMapMgr:GetInstance():GetBuildActPos(point)
        MazeMapMgr:GetInstance():SetPointEffectGo(point, effectGo)
    end
    KTool.SetActive(effectGo, true)

    --ui动画
    self:SetAnimationActive(point, true)
    KTool.SetActive(go, true)
end

--刷新位置
function UIMazeDialog:UpdatePointViewGoPos(point)
    if not point then return end

    local go = point.viewGo
    if not go then return end

    local worldPos = MazeMapMgr:GetInstance():GetBuildActPos(point)
    local cam = MazeMapMgr:GetInstance().mazeCam
    local pos = CS.UnityEngine.RectTransformUtility.WorldToScreenPoint(cam, worldPos)

    pos = CfUtils.ChangePosByCanvas(pos)

    local btn = go.transform:Find("btn"):GetComponent(typeof(Button))
    go.transform.anchoredPosition = Vector3(pos.x, pos.y + btn.transform:GetComponent("RectTransform").sizeDelta.y * 0.5 + 40, 0) 
end

--开始倒计时
function UIMazeDialog:StartCountDown()
    self._timer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if count <= 0 then
            --时间结束 没有完成
            local a = CfUtils.GetTimeHMS(count)
            CfUtils.FillText(self.time, a)
            GameUtils.SecondConfirm(localize("规定时间未通关请退出"), function()
                GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {
                    { id = Constants.UITypeIds.UIHomeView },{}
                }, Constants.LoadingType.MainHome, true)
            end, function(  )
                GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {
                    { id = Constants.UITypeIds.UIHomeView },{}
                }, Constants.LoadingType.MainHome, true)
            end)
        else
            local a = CfUtils.GetTimeHMS(count)
            CfUtils.FillText(self.time, a)
        end
    end, self.timeRemaining, false, true, true)
end


