--绘制点开的大地图
function UIMazeDialog:FillViewMap()
    local map = MazeMapMgr:GetInstance():GetMapData()
    if not map then
        return
    end

    for i = 1, #map do
        local linePoints = map[i]
        for k, v in pairs(linePoints) do
            local go = self.viewMmap.transform:Find("point"..v.line..v.row)
            if not go then
                go = GameObject.Instantiate(self.point2.gameObject, self.viewMmap.transform)
                go.name = "point"..v.line..v.row  
            end
            self:FillViewMapPoint(go, v)
            KTool.SetActive(go, true)
            go.transform.anchoredPosition = v.viewMapPos

            local rect = self.viewMmap.transform:GetComponent(typeof(RectTransform))
            rect.sizeDelta = Vector2(rect.sizeDelta.x, v.viewMapPos.y + 120)

            --if not self.isFillViewMap then
                local nextPoints = MazeMapMgr:GetInstance():GetNextPoints(v)
                if nextPoints then 
                    for j, m in pairs(nextPoints) do
                        self:FillLine(v, m, self.mapType.viewMap)
                    end
                end
            --end
        end
    end 
    --if not self.isFillViewMap then
        --self.isFillViewMap = true
    --end
    self:RefeshViewMapPoint()
end

--绘制小地图
function UIMazeDialog:FillMiniMap()
    local map = MazeMapMgr:GetInstance():GetMapData()
    if not map then
        return
    end

    for i = 1, #map do
        local linePoints = map[i]
        for k, v in pairs(linePoints) do
            local go = GameObject.Instantiate(self.point.gameObject, self.map.transform)
            go.name = "point"..v.line..v.row  
            self:FillMiniMapPoint(go, v)
            KTool.SetActive(go, true)
            go.transform.anchoredPosition = v.miniMapPos

            local nextPoints = MazeMapMgr:GetInstance():GetNextPoints(v)
            if nextPoints then 
                for j, m in pairs(nextPoints) do
                    self:FillLine(v, m, self.mapType.miniMap)
                end
            end
        end
    end 
    self:RefeshMiniMapPoint()
end

