function UIMazeDialog:FillViewMapPoint(pointGo, point)
    if not pointGo or not point then
        return
    end
    local scr = CfUtils.GetLuaScr(pointGo, UIMazeBigMapNode)
    if scr then
        scr:Refresh(point, function()
            --如果不是当前点
            if not MazeMapMgr:GetInstance():IsCurPoint(point) then
                UIModule.OpenDialog({id = Constants.UITypeIds.UIViewPointEventDialog, parameters = {point = point, isViewMap = true}})
            end
            if not MazeMapMgr:GetInstance():IsSamePoint(point, self.curSelectMapPoint) then
                self:RefeshCurSelectPoint(point)
            end 
        end)
        scr:RefreshCurPosNode(self:IsCurSelectPoint(point))
    end
end

--刷新大地图当前选择的点
function UIMazeDialog:RefeshCurSelectPoint(point)
    if not point then return end
    self.lastSelectMapPoint = self.curSelectMapPoint
    self.curSelectMapPoint = point
    self:FillViewMapPoint(self.viewMmap.transform:Find("point"..self.curSelectMapPoint.line..self.curSelectMapPoint.row), self.curSelectMapPoint)
    if self.lastSelectMapPoint then
        self:FillViewMapPoint(self.viewMmap.transform:Find("point"..self.lastSelectMapPoint.line..self.lastSelectMapPoint.row), self.lastSelectMapPoint)
    end
end

--根据当前点刷新小地图
function UIMazeDialog:RefeshMiniMapPoint()
    local curPoint = MazeMapMgr:GetInstance().curPoint
    if curPoint then
        local points = MazeMapMgr:GetInstance():GetPointsByLine(curPoint.line + 1)
        if points then
            for k, v in pairs(points) do
                CfUtils.SetScale(self.map.transform:Find("point"..v.line..v.row), Vector3(1.1, 1.1, 1.1))
                self:FillMiniMapPoint(self.map.transform:Find("point"..v.line..v.row), v)
            end
        end
   
        points = MazeMapMgr:GetInstance():GetPointsByLine(curPoint.line)
        if points then
            for k, v in pairs(points) do
                CfUtils.SetScale(self.map.transform:Find("point"..v.line..v.row), Vector3(1, 1, 1))
                self:FillMiniMapPoint(self.map.transform:Find("point"..v.line..v.row), v)
            end
        end

        --刷新线
        local lastLinePoints = MazeMapMgr:GetInstance():GetPointsByLine(curPoint.line - 1)
        if lastLinePoints and points then
            for k, v in pairs(lastLinePoints) do
                for m, n in pairs(points) do
                    self:RefeshLine(v, n, self.mapType.miniMap)
                end
            end
        end
    end 

    local lastPoint = MazeMapMgr:GetInstance().lastPoint
    if lastPoint then
        self:FillMiniMapPoint(self.map.transform:Find("point"..lastPoint.line..lastPoint.row), lastPoint)
    end
end

--结束移动后大地图的刷新
function UIMazeDialog:RefeshViewMapPoint()
    local lastPoint = MazeMapMgr:GetInstance().lastPoint
    if lastPoint then
        self:FillViewMapPoint(self.viewMmap.transform:Find("point"..lastPoint.line..lastPoint.row), lastPoint)
    end

    local curPoint = MazeMapMgr:GetInstance().curPoint
    if curPoint then
        local nextLinePoints = MazeMapMgr:GetInstance():GetPointsByLine(curPoint.line + 1)
        if nextLinePoints then
            for k, v in pairs(nextLinePoints) do
                CfUtils.SetScale(self.viewMmap.transform:Find("point"..v.line..v.row), Vector3(1.1, 1.1, 1.1))
                self:FillViewMapPoint(self.viewMmap.transform:Find("point"..v.line..v.row), v)
            end
        end
   
            local curLinePoints = MazeMapMgr:GetInstance():GetPointsByLine(curPoint.line)
            if curLinePoints then
                for k, v in pairs(curLinePoints) do
                    CfUtils.SetScale(self.viewMmap.transform:Find("point"..v.line..v.row), Vector3(1, 1, 1))
                    self:FillViewMapPoint(self.viewMmap.transform:Find("point"..v.line..v.row), v)
                end
            end

        --刷新线
        local lastLinePoints = MazeMapMgr:GetInstance():GetPointsByLine(curPoint.line - 1)
        if lastLinePoints and curLinePoints then
            for k, v in pairs(lastLinePoints) do
                for m, n in pairs(curLinePoints) do
                    self:RefeshLine(v, n, self.mapType.viewMap)
                end
            end
        end
    end 
end

--刷新连线
function UIMazeDialog:RefeshLine(fromPoint, toPoint, mapType)
    if not fromPoint or not toPoint then
        return
    end

    local parGo 
    if checkNumber(mapType) == self.mapType.miniMap then
        parGo = self.lineWays
    elseif checkNumber(mapType) == self.mapType.viewMap then
        parGo = self.viewMaplineWays
    end
    if not parGo then return end

    local lineGo = parGo.transform:Find("line"..fromPoint.line..fromPoint.row..toPoint.line..toPoint.row)
    if not lineGo then
        return
    end

    local curPoint = MazeMapMgr:GetInstance():GetCurPoint()
    if not curPoint then
        return
    end

    local lineType
    if fromPoint.line < curPoint.line then
        local fIsPass = MazeMgr:GetInstance():IsPassCurPoint(fromPoint)
        local tIsPass = MazeMgr:GetInstance():IsPassCurPoint(toPoint)
        --如果都有历史记录
        if fIsPass and tIsPass then
            lineType = self.lineType.Big
            -------------可能会删
        elseif fIsPass and MazeMapMgr:GetInstance():IsCurPoint(toPoint) then
            lineType = self.lineType.Big
        else
            lineType = self.lineType.Small
        end
    elseif fromPoint.line == curPoint.line then
        if not MazeMapMgr:GetInstance():IsCurPoint(fromPoint) then
            lineType = self.lineType.Small
        else
            lineType = self.lineType.Middle
        end
    else  
        lineType = self.lineType.Middle
    end
    self:ChangeLineImage(lineGo, lineType, mapType)
end

--修改线的表现
function UIMazeDialog:ChangeLineImage(go, lineType, mapType) 
    if not go then
        return
    end

    local col
    local sizeX = 1
    if checkNumber(mapType) == self.mapType.miniMap then
        if checkNumber(lineType) == self.lineType.Small then
            col = Color.New(75/255, 75/255, 75/255, 255/255)
            sizeX = 1
        elseif checkNumber(lineType) == self.lineType.Middle then
            col = Color.New(160/255, 160/255, 160/255, 255/255)
            sizeX = 1
        elseif checkNumber(lineType) == self.lineType.Big then
            col = Color.New(255/255, 255/255, 255/255, 255/255)
            sizeX = 1
        end
    elseif checkNumber(mapType) == self.mapType.viewMap then
        if checkNumber(lineType) == self.lineType.Small then
            col = Color.New(75/255, 75/255, 75/255, 255/255)
            sizeX = 2
        elseif checkNumber(lineType) == self.lineType.Middle then
            col = Color.New(160/255, 160/255, 160/255, 255/255)
            sizeX = 2
        elseif checkNumber(lineType) == self.lineType.Big then
            col = Color.New(255/255, 255/255, 255/255, 255/255)
            sizeX = 4
        end
    end

    local rt = go:GetComponent(typeof(RectTransform))
    CfUtils.SetImageColor(go, col)
    rt.sizeDelta = Vector2(rt.sizeDelta.x, sizeX)
end

--设置俩点间的线段
function UIMazeDialog:FillLine(fromPoint, toPoint, mapType)
    if not fromPoint or not toPoint then
        return
    end

    local posBegin
    local posEnd

    local parGo 
    if checkNumber(mapType) == self.mapType.miniMap then
        parGo = self.lineWays
        posBegin = fromPoint.miniMapPos
        posEnd = toPoint.miniMapPos
    elseif checkNumber(mapType) == self.mapType.viewMap then
        parGo = self.viewMaplineWays
        posBegin = fromPoint.viewMapPos
        posEnd = toPoint.viewMapPos
    end

    local go = GameObject.Instantiate(self.lineWay.gameObject, parGo.transform)
    local name = "line"..fromPoint.line..fromPoint.row..toPoint.line..toPoint.row
    go.name = name

    go.transform.anchoredPosition = posBegin
    local dir = posEnd - posBegin
    go.transform:GetComponent(typeof(RectTransform)).sizeDelta = Vector2(dir.magnitude, go.transform:GetComponent(typeof(RectTransform)).rect.height)    --距离

    local rotation = Quaternion.New()
    rotation.eulerAngles = Vector3.New(0, 0, CfUtils.AnglePos(posBegin,posEnd))
    go.transform:GetComponent(typeof(RectTransform)).localRotation = rotation    --角度

    self:RefeshLine(fromPoint, toPoint, mapType)
    KTool.SetActive(go, true)
end


