--移动结束事件 
function UIMazeDialog:OnMazeMoveEnd()
    local curPoint = MazeMapMgr:GetInstance():GetCurPoint()
    if not curPoint then
        return
    end

    local pointStr = checkString(MazeMgr:GetInstance():GetCurPointAndName())
    CfUtils.FillText(self.curPass, pointStr)

    --刷新地图
    self:RefeshViewMapPoint()
    self:RefeshMiniMapPoint()
    self:RefeshCurSelectPoint(curPoint)
    
    --没有通关  激活事件点
    if not MazeMgr:GetInstance():IsPassCurPoint(curPoint) then
        MazeMgr:GetInstance():ActiveEvent()
    else
        --boss 关卡特殊处理
        if curPoint.type == Constants.MazePointType.BossBattle then   
            --[[   
            if MazeMgr:GetInstance():IsDrawReward() then      
                GameUtils.SecondConfirm(localize("恭喜通关"), function(  )
                    GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {
                        { id = Constants.UITypeIds.UIHomeView },{}
                    }, Constants.LoadingType.MainHome, true)
                end, function(  )
                    GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {
                        { id = Constants.UITypeIds.UIHomeView },{}
                    }, Constants.LoadingType.MainHome, true)
                end)
            end
            ]]
            --[[
            local t = MazeMgr:GetInstance():GetRewardData()
            if t then
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = t } })         
            end 
            ]]  
        else
            self:OnMainUIActive({isTrue = true})
            self:RefeshPointMessage()
        end
    end
end

