--迷宫主界面ui显示和隐藏
function UIMazeDialog:OnMainUIActive(body)
    if not body then return end
    local isTrue = body.isTrue
    if isTrue then 
        --如果是大地图打开
        if self.isShowBigMap then
            self:RefeshBackWithBigMap()
        else
            KTool.SetActive(self.smallMap.gameObject, true)
            self:SetUIActive(isTrue)
            --界面打开的时候刷新一下
            self:ShowCommonTop()
        end
        KTool.SetActive(self.pointsMessage.gameObject, true)
        KTool.SetActive(self.BtnChest.gameObject, true)
        KTool.SetActive(self.Root.transform:Find("Bottom"), true)
    else
        KTool.SetActive(self.Root.transform:Find("Bottom"), false)
        KTool.SetActive(self.pointsMessage.gameObject, false)
        KTool.SetActive(self.smallMap.gameObject, false)
        KTool.SetActive(self.BtnChest.gameObject, false)
        self:SetUIActive(false)
    end
end

