--迷宫ui整体关闭与显示
function UIMazeDialog:OnMazeUIAllActive(body)
    if not body then return end
    local isTrue = body.isTrue
    if isTrue then 
        CfUtils.SetTopCommonActive(true)
        self.controller.gameObject:GetComponent("CanvasGroup").alpha = 1
    else
