--[[
    @desc: 获取一个点的实例
    author:{author}
    time:2020-04-13 14:34:53
    @return:
]]
function UIMazeDialog:GetPointGo()
    local go
    if #self.pointGoPool > 0 then
        go = self.pointGoPool[1]
        table.remove(self.pointGoPool, 1)
    else
        local loader = ResourceModule.LoadBundleSync("Prefabs/Maze/UIBuildMessage.prefab", nil, true)
        if loader.IsSuccess then
            go = loader:Instantiate(self.pointsMessage.transform)
        end
        loader:Release()
    end
    return go
end

--[[
    @desc: 获取一个特效的实例
    author:{author}
    time:2020-04-13 14:34:53
    @return:
]]
function UIMazeDialog:GetPointEffectGo(type)
    type = checkNumber(type)
    local go
    local pool = self.pointEffectGoPool[type]
    --如果有这个对象的池
    if pool then
        if #pool > 0 then
            go = pool[1]
            table.remove(pool, 1)
        end
    end

    local effectGoPar = MazeMapMgr:GetInstance().pointPar
    --如果没有取到特效 实例化
    if not go then
        if IsNull(self.effectLoaders[CfUtils.GetMazeEffectGoPath(type)]) then
            self.effectLoaders[CfUtils.GetMazeEffectGoPath(type)] = CS.Engine.Modules.ResourceModule.LoadBundleSync(CfUtils.GetMazeEffectGoPath(type), nil, true)
        end
        if self.effectLoaders[CfUtils.GetMazeEffectGoPath(type)].IsSuccess then
            go = CfUtils.InstantiateGo(self.effectLoaders[CfUtils.GetMazeEffectGoPath(type)].ResultObject, effectGoPar)
        end  
    end

    return go
end

--特效放入回收池
function UIMazeDialog:PullPointEffectGoPool(type, go)
    if not go then
        return
    end
    type = checkNumber(type)
    if not self.pointEffectGoPool[type] then
        self.pointEffectGoPool[type] = {}
    end
    table.insert(self.pointEffectGoPool[type], go)
end

--回收视图点信息
function UIMazeDialog:ClearPointMessageAll()
    if self.lastPreviewPoint then
        for k, point in pairs(self.lastPreviewPoint) do
            self:SetAnimationActive(point, false)
            --放入对象池
            table.insert(self.pointGoPool, point.viewGo)
            self:PullPointEffectGoPool(point.type, point.effectGo)
            --先设为false
            KTool.SetActive(point.viewGo, false)
            KTool.SetActive(point.effectGo, false)

            --置空
            MazeMapMgr:GetInstance():SetPointViewGo(point)
            MazeMapMgr:GetInstance():SetPointEffectGo(point)
        end
    end
    self.lastPreviewPoint = {}
end

--设置点信息的动画显示
function UIMazeDialog:SetAnimationActive(point, isTrue)
    if not point then
        return
    end
    local amGo = point.viewGo
    if not amGo then
        return
    end

    local amName
    --该点需要选择圣物
    if checkNumber(point.isNeedSelectRelic) == 1 and (checkNumber(point.type) == Constants.MazePointType.CreamBattle or
      checkNumber(point.type) == Constants.MazePointType.OrdinaryBattle) then
        amName = "MazeAnim_Buff"
    else
        amName = "MazeAnim_"..checkString(point.type)
    end
    local amNode = amGo.transform:Find(amName)

    if not amNode then
        if isTrue then
            if IsNull(self.animLoaders[CfUtils.GetMazeViewPointAnimPath(point)]) then
                self.animLoaders[CfUtils.GetMazeViewPointAnimPath(point)] = CS.Engine.Modules.ResourceModule.LoadBundleSync(CfUtils.GetMazeViewPointAnimPath(point), nil, true)
            end
            if self.animLoaders[CfUtils.GetMazeViewPointAnimPath(point)].IsSuccess then
                amNode = CfUtils.InstantiateGo(self.animLoaders[CfUtils.GetMazeViewPointAnimPath(point)].ResultObject, amGo)
            end  
            if amNode then
                amNode.name = amName
            end
        end
    end
    if not amNode then
        return
    end
    KTool.SetActive(amNode, isTrue and true or false)

    --选择圣物的时候的动画  就不特殊判断了 false的直接找一下置为false
    if not isTrue and (checkNumber(point.type) == Constants.MazePointType.CreamBattle or
      checkNumber(point.type) == Constants.MazePointType.OrdinaryBattle) then
        amNode = amGo.transform:Find("typeBuff")
        if amNode then
            KTool.SetActive(amNode, false)
        end
    end
end

--判断一个点是不是当前地图选择的点
function UIMazeDialog:IsCurSelectPoint(point)
    if self.curSelectMapPoint then
        if checkNumber(point.line) == checkNumber(self.curSelectMapPoint.line) and checkNumber(point.row) == checkNumber(self.curSelectMapPoint.row) then
            return true 
        end
    elseif checkNumber(point.line) == checkNumber(MazeMapMgr:GetInstance().curPoint.line) and checkNumber(point.row) == checkNumber(MazeMapMgr:GetInstance().curPoint.row) then
        return true
    end
    return false
end

function UIMazeDialog:SetUIActive(isTrue)
    if not isTrue then
        local anim = self.left.transform:GetComponent("Animation")
        if anim then
            anim:Stop()
        end
    end
    KTool.SetActive(self.left.gameObject, isTrue)
end

