function UIMazeDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
    end
    ))
    return coWait
end

function UIMazeDialog:OnFinalize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            if not isNull(self.effectLoaders) then
                for k, v in pairs(self.effectLoaders) do
                    v:Release(true)
                    v = nil
                end 
            end
            if not isNull(self.animLoaders) then
                for k, v in pairs(self.animLoaders) do
                    v:Release(true)
                    v = nil
                end 
            end

            Events.RemoveListener(Constants.EventNames.MazeMoveEnd, self.EventMazeMoveEnd)
            Events.RemoveListener(Constants.EventNames.MazeRefeshPreview, self.EventMazeRefeshPreview)
            Events.RemoveListener(Constants.EventNames.MazeUpdataPreview, self.EventMazeUpdataPreview)
            Events.RemoveListener(Constants.EventNames.MazeMainUIActive, self.EventMainUIActive)
            Events.RemoveListener(Constants.EventNames.MazeClosePreview, self.EventClosePreview)
            Events.RemoveListener(Constants.EventNames.MazeHeroNumChange, self.EventMazeHeroNumChange)
            Events.RemoveListener(Constants.EventNames.MazeUIAllActive, self.EventMazeMazeUIAllActive)

            if not isNull(self._timer) then
                ---删除计时器
                CDTimerModule.GetInstance():RemoveCD(self._timer)
                self._timer = nil
            end
        end
        CfUtils.RefreshTopCommonEntrance()
        ----移除不需要的资源
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIMazeDialog